window.__votdWeek && window.__votdWeek({"week":"2028-07-31","reading":"Alma 39–42","days":[{"d":"2028-07-31","ref":"Alma 39:9","b":"Alma","c":39,"v":9,"he":"וְעַתָּה בְּנִי חָפַצְתִּי כִּי־תָשׁוּב וְתַעֲזֹב אֶת־חַטֹּאתֶיךָ וְלֹא תֵלֵךְ עוֹד אַחֲרֵי תַאֲוַת עֵינֶיךָ אַךְ תִּגְדֹּר אֶת־נַפְשְׁךָ מִכׇּל הַדְּבָרִים הָאֵלֶּה כִּי־אִם לֹא־תַעֲשֶׂה זֹאת לֹא־תוּכַל לָרֶשֶׁת אֶת־מַלְכוּתוֹ הוֹי זְכֹר וְקַבֵּל עָלֶיךָ וּגְדֹר אֶת־נַפְשְׁךָ בַּדְּבָרִים הָאֵלֶּה׃","en":"Now my son, I would that ye should repent and forsake your sins, and go no more after the lusts of your eyes, but cross yourself in all these things; for except ye do this ye can in nowise inherit the kingdom of God. Oh, remember, and take it upon you, and cross yourself in these things."},{"d":"2028-08-01","ref":"Alma 39:14","b":"Alma","c":39,"v":14,"he":"אַל תְּבַקֵּשׁ עֹשֶׁר וְהַבְלֵי הָעוֹלָם הַזֶּה כִּי הִנֵּה לֹא־תוּכַל לָשֵׂאת אוֹתָם עִמָּךְ׃","en":"Seek not after riches nor the vain things of this world; for behold, you cannot carry them with you."},{"d":"2028-08-02","ref":"Alma 40:8","b":"Alma","c":40,"v":8,"he":"וְעַתָּה אִם־יֵשׁ יוֹתֵר מִמּוֹעֵד אֶחָד לָקוּם בְּנֵי־הָאָדָם אַחַת הִיא כִּי־לֹא יָמוּתוּ כֻלָּם כְּאֶחָד וְגַם־זֹאת אַחַת הִיא הַכֹּל כְּיוֹם אֶחָד לֵאלֹהִים וְהוּא מוֹנֶה אֶת־הַיָּמִים לִבְנֵי הָאָדָם׃","en":"Now whether there is more than one time appointed for men to rise it mattereth not; for all do not die at once, and this mattereth not; all is as one day with God, and time only is measured unto men."},{"d":"2028-08-03","ref":"Alma 40:25","b":"Alma","c":40,"v":25,"he":"וְאָז יַזְהִירוּ הַצַּדִּיקִים בְּמַלְכוּתוֹ׃","en":"And then shall the righteous shine forth in the kingdom of God."},{"d":"2028-08-04","ref":"Alma 41:10","b":"Alma","c":41,"v":10,"he":"אַל תַּחְשֹׁב כִּי יַעַן נֶאֱמַר עַל־דְּבַר הַהֲשָׁבָה כִּי תּוּשַׁב מֵחֵטְא אֶל אֹשֶׁר הִנֵּה אֹמֵר אֲנִי לְךָ הָרֶשַׁע לֹא־הָיָה מֵעוֹלָם אֹשֶׁר׃","en":"Do not suppose, because it has been spoken concerning restoration, that ye shall be restored from sin to happiness. Behold, I say unto you, wickedness never was happiness."},{"d":"2028-08-05","ref":"Alma 42:26","b":"Alma","c":42,"v":26,"he":"וְכֵן מֵבִיא אֱלֹהִים אֶת־עֲצוֹתָיו הַגְּדוֹלוֹת אֲשֶׁר־לְעוֹלָם אֲשֶׁר הוּכְנוּ מִמּוֹסְדוֹת הָעוֹלָם וְכֵן בָּאָה יְשׁוּעַת בְּנֵי־הָאָדָם וּגְאֻלָּתָם וְגַם אׇבְדָנָם וְעׇנְיָם׃","en":"And thus God bringeth about his great and eternal purposes, which were prepared from the foundation of the world. And thus cometh about the salvation and the redemption of men, and also their destruction and misery."},{"d":"2028-08-06","ref":"Alma 42:27","b":"Alma","c":42,"v":27,"he":"לָכֵן בְּנִי כׇּל הֶחָפֵץ יָבוֹא וְיִשְׁתֶּה מִמֵּי הַחַיִּים חִנָּם וְכׇל־אֲשֶׁר לֹא יַחְפֹּץ לָבוֹא לֹא יְאֻלַּץ לָבוֹא אַךְ בַּיּוֹם הָאַחֲרוֹן יוּשַׁב לוֹ כְּפִי מַעֲשָׂיו׃","en":"Therefore, O my son, whosoever will come may come and partake of the waters of life freely; and whosoever will not come the same is not compelled to come; but in the last day it shall be restored unto him according to his deeds."}]});
